}

.demo-title {
 position: absolute;
 top: 20px;
 left: 20px;
 font-size: 24px;
 font-weight: bold;
 color: var(--primary-dark);
}

/* Info Modal */
.info-modal {
 display: none;
 position: fixed;
 z-index: 1001;
 left: 0;
 top: 0;
 width: 100%;
 height: 100%;
 overflow: auto;
 background-color: rgba(0,0,0,0.4);
}

.info-content {
 background-color: white;
 margin: 10% auto;
 padding: 20px;
 border-radius: var(--border-radius);
 width: 80%;
 max-width: 500px;
 box-shadow: var(--shadow);
 position: relative;
}

.close-info {
 color: #aaa;
 float: right;
 font-size: 28px;
 font-weight: bold;
 cursor: pointer;
}

.close-info:hover {
 color: black;
}

/* Chat Button & Animation Effects */
.chat-button {
 position: fixed;
 bottom: 30px;
 right: 30px;
 width: 60px;
 height: 60px;
 background-color: var(--primary-color);
 color: white;
 border-radius: 50%;
 display: flex;
 justify-content: center;
 align-items: center;
 cursor: pointer;
 box-shadow: var(--shadow);
 z-index: 999;
 transition: var(--transition);
}

.chat-button i {
 font-size: 24px;
}

.chat-button:hover {
 background-color: var(--primary-dark);
 transform: scale(1.05);
}

/* Concentric Rings Animation */
.chat-button::before,
.chat-button::after {
 content: '';
 position: absolute;
 border-radius: 50%;
 background-color: rgba(0, 86, 179, 0.3); /* Using primary color with opacity */
 z-index: -1;
 animation: pulse 2s infinite;
}

.chat-button::before {
 width: 80px;
 height: 80px;
 animation-delay: 0.5s;
}

.chat-button::after {
 width: 100px;
 height: 100px;
 animation-delay: 1s;
}

@keyframes pulse {
 0% {
 transform: scale(0.5);
 opacity: 0.8;
 }
 70% {
 transform: scale(1.2);
 opacity: 0;
 }
 100% {
 transform: scale(1.2);
 opacity: 0;
 }
}

/* Notification Cloud */
.notification-cloud {
 position: absolute;
 top: -15px;
 right: -10px;
 background-color: #FF5252;
 color: white;
 border-radius: 20px;
 font-size: 12px;
 padding: 3px 8px;
 box-shadow: 0 2px 5px rgba(0, 0, 0, 0.2);
 opacity: 0;
 transform: scale(0);
 transition: all 0.3s ease;
 z-index: 1000;
}

.notification-cloud.visible {
 opacity: 1;
 transform: scale(1);
}

/* Speech bubble shape for the cloud */
.notification-cloud::after {
 content: '';
 position: absolute;
 bottom: -5px;
 right: 10px;
 width: 10px;
 height: 10px;
 background-color: #FF5252;
 transform: rotate(45deg);
 z-index: -1;
}

/* Enhanced Info Modal Styles */
.info-content {
 background-color: white;
