.chat-button::after {
 content: '';
 position: absolute;
 border-radius: 50%;
 background-color: rgba(0, 86, 179, 0.3); /* Using primary color with opacity */
 z-index: -1;
 animation: pulse 2s infinite;
}

.chat-button::before {
 width: 80px;
 height: 80px;
 animation-delay: 0.5s;
}

.chat-button::after {
 width: 100px;
 height: 100px;
 animation-delay: 1s;
}

@keyframes pulse {
 0% {
 transform: scale(0.5);
 opacity: 0.8;
 }
 70% {
 transform: scale(1.2);
 opacity: 0;
 }
 100% {
 transform: scale(1.2);
 opacity: 0;
 }
}

/* Notification Cloud */
.notification-cloud {
 position: absolute;
 top: -15px;
 right: -10px;
 background-color: #FF5252;
 color: white;
 border-radius: 20px;
 font-size: 12px;
 padding: 3px 8px;
 box-shadow: 0 2px 5px rgba(0, 0, 0, 0.2);
 opacity: 0;
 transform: scale(0);
 transition: all 0.3s ease;
 z-index: 1000;
}

.notification-cloud.visible {
 opacity: 1;
 transform: scale(1);
}

/* Speech bubble shape for the cloud */
.notification-cloud::after {
 content: '';
 position: absolute;
 bottom: -5px;
 right: 10px;
 width: 10px;
 height: 10px;
 background-color: #FF5252;
 transform: rotate(45deg);
 z-index: -1;
}

/* Enhanced Info Modal Styles */
.info-content {
 background-color: white;
