}

/* Chat Container */
.chat-container {
 position: fixed;
 bottom: 100px;
 right: 30px;
 width: 360px;
 height: 600px;
 background-color: white;
 border-radius: var(--border-radius);
 overflow: hidden;
 box-shadow: var(--shadow);
 display: flex;
 flex-direction: column;
 z-index: 1000;
 opacity: 0;
 pointer-events: none;
 transform: translateY(20px);
 transition: var(--transition);
}

.chat-container.active {
 opacity: 1;
 pointer-events: all;
 transform: translateY(0);
}

/* Chat Header */
.chat-header {
 background-color: var(--primary-color);
 color: white;
 padding: 15px;
 display: flex;
 justify-content: space-between;
 align-items: center;
}

.header-content {
 display: flex;
 align-items: center;
}

.logo {
 width: 40px;
 height: 40px;
 border-radius: 50%;
 margin-right: 12px;
 background-color: white;
 object-fit: contain;
}

.header-text h3 {
 font-size: 16px;
 margin-bottom: 2px;
}

.university-name {
 font-size: 10px;
 opacity: 0.9;
}

.header-actions {
 display: flex;
}

.action-btn {
 background: transparent;
 border: none;
 color: white;
 margin-left: 15px;
 cursor: pointer;
 font-size: 20px;
 transition: var(--transition);
}

.action-btn:hover {
 transform: scale(1.1);
}

/* Chat Body */
.chat-body {
 flex: 1;
 padding: 15px;
 overflow-y: auto;
 background-color: #f9f9f9;
}

.chat-message {
 margin-bottom: 15px;
 display: flex;
 flex-direction: column;
 max-width: 85%;
}

.message-content {
 padding: 12px 15px;
 border-radius: 18px;
 box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
 position: relative;
 word-wrap: break-word;
}

.message-content p {
 margin-bottom: 8px;
}

.message-content p:last-child {
 margin-bottom: 0;
}

.message-content a {
 color: var(--primary-color);
 text-decoration: underline;
 word-break: break-all;
}

.bot {
 align-self: flex-start;
}

.bot .message-content {
 background-color: var(--bot-message-bg);
 color: var(--text-color);
 border-bottom-left-radius: 4px;
}

.user {
 align-self: flex-end;
}

.user .message-content {
 background-color: var(--user-message-bg);
 color: var(--user-message-text);
 border-bottom-right-radius: 4px;
}

/* Typing Indicator */
.typing-indicator {
 display: flex;
 align-items: center;
 padding: 10px 15px;
 background-color: var(--bot-message-bg);
 border-radius: 18px;
 max-width: 100px;
 margin-bottom: 15px;
}

.typing-indicator span {
 height: 8px;
 width: 8px;
 margin: 0 2px;
 background-color: #999;
 border-radius: 50%;
 display: inline-block;
 animation: typing 1.4s infinite ease-in-out both;
}

.typing-indicator span:nth-child(1) {
 animation-delay: 0s;
}

.typing-indicator span:nth-child(2) {
 animation-delay: 0.2s;
}

.typing-indicator span:nth-child(3) {
 animation-delay: 0.4s;
}

@keyframes typing {
 0% { transform: scale(1); }
 50% { transform: scale(1.5); }
 100% { transform: scale(1); }
}

/* Chat Footer */
.chat-footer {
 padding: 10px 15px;
 background-color: white;
 display: flex;
 align-items: flex-end;
 border-top: 1px solid #eee;
}

#user-input {
 flex: 1;
 border: 1px solid #ddd;
 border-radius: 20px;
 padding: 10px 15px;
 font-size: 14px;
 max-height: 120px;
 overflow-y: auto;
 resize: none;
 outline: none;
 transition: var(--transition);
}

#user-input:focus {
 border-color: var(--primary-light);
}

#send-btn {
 background-color: var(--primary-color);
 color: white;
 border: none;
 width: 40px;
 height: 40px;
 border-radius: 50%;
 margin-left: 10px;
 cursor: pointer;
 display: flex;
 justify-content: center;
 align-items: center;
 transition: var(--transition);
}

#send-btn:hover {
 background-color: var(--primary-dark);
}

#send-btn:disabled {
 background-color: #ccc;
 cursor: not-allowed;
}

/* Timer Styles */
#timer-display {
 font-size: 14px;
 color: var(--primary-dark);
 margin-right: 10px; /* Space between timer and send button */
 visibility: hidden; /* Initially hidden */
 opacity: 0;
 transition: visibility 0s, opacity 0.3s ease;
 padding: 10px;
}
#timer-display.active{
 visibility: visible;
 opacity: 1;
}

/* Mobile Responsive Styles */
@media (max-width: 768px) {
 .chat-container.active {
 width: 100%;
 height: 100%;
 bottom: 0;
 right: 0;
 border-radius: 0;
 }

 .chat-button {
 bottom: 20px;
 right: 20px;
 }

 .info-content {
 width: 90%;
 margin: 20% auto;
 }

 .links-container {
 flex-direction: column;
 }

 .kgmu-link {
 flex: 1 0 100%;
 }
}


