 document.addEventListener("DOMContentLoaded", function () {
 const submenuParents = document.querySelectorAll("nav .upper-nav ul ul li");

 submenuParents.forEach(parent => {
 const submenu = parent.querySelector("ul");

 if (submenu) {
 parent.addEventListener("mouseenter", function () {
 submenu.classList.remove("open-left"); // reset direction
 submenu.style.visibility = "hidden"; // hide to measure
 submenu.style.display = "block"; // show temporarily

 const rect = submenu.getBoundingClientRect();
 const willOverflow = rect.right > window.innerWidth;

 submenu.style.display = ""; // restore
 submenu.style.visibility = "";

 if (willOverflow) {
 submenu.classList.add("open-left");
 }
 });

 parent.addEventListener("mouseleave", function () {
 submenu.classList.remove("open-left");
 });
 }
 });
 });




