}

/* Speech bubble shape for the cloud */
.notification-cloud::after {
 content: '';
 position: absolute;
 bottom: -5px;
 right: 10px;
 width: 10px;
 height: 10px;
 background-color: #FF5252;
 transform: rotate(45deg);
 z-index: -1;
}

/* Enhanced Info Modal Styles */
.info-content {
 background-color: white;
 margin: 7% auto;
 padding: 25px;
 border-radius: var(--border-radius);
 width: 80%;
 max-width: 600px;
 box-shadow: var(--shadow);
 position: relative;
}

.developer-profile {
 display: flex;
 flex-direction: column;
 align-items: center;
 margin-bottom: 20px;
}

.profile-image-container {
 width: 120px;
 height: 120px;
 border-radius: 50%;
 overflow: hidden;
 border: 3px solid var(--primary-color);
 margin-bottom: 15px;
 box-shadow: 0 4px 8px rgba(0, 0, 0, 0.2);
}

.profile-image {
 width: 100%;
 height: 100%;
 object-fit: cover;
}

.developer-profile h2 {
 color: var(--primary-dark);
 margin-bottom: 5px;
}

.credentials {
 color: var(--text-light);
 font-style: italic;
 margin-bottom: 15px;
}

.developer-bio {
 margin-bottom: 25px;
 line-height: 1.6;
}

.developer-bio p {
 margin-bottom: 15px;
 text-align: justify;
}

.kgmu-quick-links {
 background-color: var(--secondary-color);
 padding: 15px;
 border-radius: var(--border-radius);
 margin-bottom: 20px;
}

.kgmu-quick-links h3 {
 color: var(--primary-dark);
 margin-bottom: 15px;
 text-align: center;
}

.links-container {
 display: flex;
 flex-wrap: wrap;
 justify-content: space-between;
 gap: 10px;
}

.kgmu-link {
 flex: 1 0 45%;
 padding: 10px;
 background-color: white;
 border-radius: var(--border-radius);
 text-decoration: none;
 color: var(--primary-color);
 text-align: center;
 transition: var(--transition);
 display: flex;
 align-items: center;
 justify-content: center;
 gap: 8px;
}

.kgmu-link:hover {
 background-color: var(--primary-color);
 color: white;
 transform: translateY(-3px);
 box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
}

.connect-section {
 text-align: center;
}

.connect-section h3 {
 color: var(--primary-dark);
 margin-bottom: 15px;
}

.social-icons {
 display: flex;
 justify-content: center;
 gap: 20px;
}

.social-icons a {
 font-size: 24px;
 color: var(--primary-color);
 transition: var(--transition);
 display: flex;
 align-items: center;
 justify-content: center;
 width: 40px;
 height: 40px;
 border-radius: 50%;
}

.social-icons a:hover {
 transform: scale(1.2);
 color: var(--primary-dark);
 background-color: #d9e9ff;
}

/* Chat Container */
.chat-container {
 position: fixed;
 bottom: 100px;
 right: 30px;
 width: 360px;
 height: 600px;
 background-color: white;
 border-radius: var(--border-radius);
 overflow: hidden;
 box-shadow: var(--shadow);
 display: flex;
 flex-direction: column;
 z-index: 1000;
 opacity: 0;
 pointer-events: none;
 transform: translateY(20px);
 transition: var(--transition);
}

.chat-container.active {
 opacity: 1;
 pointer-events: all;
 transform: translateY(0);
}

/* Chat Header */
.chat-header {
 background-color: var(--primary-color);
 color: white;
 padding: 15px;
 display: flex;
 justify-content: space-between;
 align-items: center;
}

.header-content {
 display: flex;
 align-items: center;
}

.logo {
 width: 40px;
 height: 40px;
 border-radius: 50%;
 margin-right: 12px;
 background-color: white;
 object-fit: contain;
}

.header-text h3 {
 font-size: 16px;
 margin-bottom: 2px;
}

.university-name {
 font-size: 10px;
 opacity: 0.9;
}

.header-actions {
 display: flex;
}

.action-btn {
 background: transparent;
 border: none;
 color: white;
 margin-left: 15px;
 cursor: pointer;
 font-size: 20px;
 transition: var(--transition);
}

.action-btn:hover {
 transform: scale(1.1);
}

/* Chat Body */
.chat-body {
 flex: 1;
 padding: 15px;
 overflow-y: auto;
 background-color: #f9f9f9;
}

.chat-message {
 margin-bottom: 15px;
 display: flex;
 flex-direction: column;
 max-width: 85%;
}

.message-content {
 padding: 12px 15px;
 border-radius: 18px;
 box-shadow: 0 1px 2px rgba(0, 0, 0, 0.1);
 position: relative;
 word-wrap: break-word;
}

.message-content p {
 margin-bottom: 8px;
}

.message-content p:last-child {
 margin-bottom: 0;
}

.message-content a {
 color: var(--primary-color);
 text-decoration: underline;
 word-break: break-all;
}

.bot {
 align-self: flex-start;
}

.bot .message-content {
 background-color: var(--bot-message-bg);
 color: var(--text-color);
 border-bottom-left-radius: 4px;
}

.user {
 align-self: flex-end;
}

.user .message-content {
 background-color: var(--user-message-bg);
 color: var(--user-message-text);
 border-bottom-right-radius: 4px;
}

/* Typing Indicator */
.typing-indicator {
 display: flex;
 align-items: center;
 padding: 10px 15px;
 background-color: var(--bot-message-bg);
 border-radius: 18px;
 max-width: 100px;
 margin-bottom: 15px;
}

.typing-indicator span {
 height: 8px;
 width: 8px;
 margin: 0 2px;
 background-color: #999;
 border-radius: 50%;
 display: inline-block;
 animation: typing 1.4s infinite ease-in-out both;
}

.typing-indicator span:nth-child(1) {
 animation-delay: 0s;
}

.typing-indicator span:nth-child(2) {
 animation-delay: 0.2s;
}

.typing-indicator span:nth-child(3) {
 animation-delay: 0.4s;
}

@keyframes typing {
 0% { transform: scale(1); }
 50% { transform: scale(1.5); }
 100% { transform: scale(1); }
}

/* Chat Footer */
.chat-footer {
 padding: 10px 15px;
 background-color: white;
 display: flex;
 align-items: flex-end;
 border-top: 1px solid #eee;
}

#user-input {
 flex: 1;
 border: 1px solid #ddd;
 border-radius: 20px;
 padding: 10px 15px;
 font-size: 14px;
 max-height: 120px;
 overflow-y: auto;
 resize: none;
 outline: none;
 transition: var(--transition);
}

#user-input:focus {
