}

#send-btn {
 background-color: var(--primary-color);
 color: white;
 border: none;
 width: 40px;
 height: 40px;
 border-radius: 50%;
 margin-left: 10px;
 cursor: pointer;
 display: flex;
 justify-content: center;
 align-items: center;
 transition: var(--transition);
}

#send-btn:hover {
 background-color: var(--primary-dark);
}

#send-btn:disabled {
